'use client';

import { useCallback, type JSX, type Ref } from 'react';
import {
  OverlayArrow,
  Popover as RACPopover,
  PopoverContext,
  composeRenderProps,
  useSlottedContext,
  type PopoverProps as RACPopoverProps,
} from 'react-aria-components';
import styles from './popover.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

/**
 * Overlays portal to <body>, outside any ThemeScope. At open time copy the trigger's scope attributes
 * (data-strata-theme/scheme/density) and dir/lang onto the overlay root so it resolves the same tokens.
 */
const SCOPE_ATTRS = ['data-strata-theme', 'data-strata-scheme', 'data-strata-density'] as const;
function mirrorScope(overlay: HTMLElement, source: Element | null | undefined): void {
  if (!source || overlay.contains(source)) return;
  for (const name of SCOPE_ATTRS) {
    // Look each attribute up on its own: a single-tenant app themes :root and scopes only the scheme.
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
  for (const name of ['dir', 'lang']) {
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
}

export interface PopoverProps extends RACPopoverProps {
  /** Draws a small arrow pointing at the trigger. */
  showArrow?: boolean;
  ref?: Ref<HTMLElement>;
}

/**
 * A floating panel anchored to a trigger — for rich, interactive content (filters, details, small forms). Put it
 * inside a DialogTrigger next to its trigger button; it gets `role="dialog"`, traps focus and closes on Escape
 * or outside click. For short, non-interactive hints use a Tooltip.
 */
export function Popover({ showArrow, children, className, offset, ref, ...props }: PopoverProps): JSX.Element {
  const context = useSlottedContext(PopoverContext);
  const source = props.triggerRef ?? context?.triggerRef;
  const setRef = useCallback(
    (node: HTMLElement | null) => {
      if (node) mirrorScope(node, source?.current);
      if (typeof ref === 'function') return ref(node);
      if (ref) ref.current = node;
    },
    [source, ref],
  );

  return (
    <RACPopover
      {...props}
      ref={setRef}
      offset={offset ?? context?.offset ?? (showArrow ? 10 : 6)}
      className={composeRenderProps(className, (c) => cx(styles.popover, c))}
    >
      {composeRenderProps(children, (content) => (
        <>
          {showArrow && (
            <OverlayArrow className={styles.arrow}>
              <svg viewBox="0 0 12 12" aria-hidden>
                <path d="M0 0 L6 6 L12 0" />
              </svg>
            </OverlayArrow>
          )}
          {content}
        </>
      ))}
    </RACPopover>
  );
}

/* Portalled to <body>, so it re-applies the ThemeScope base (font, colour, box model). */
.popover {
  --popover-shift: 0 0;
  z-index: 50;
  box-sizing: border-box;
  min-inline-size: 0;
  max-inline-size: calc(100vw - var(--strata-space-4) * 2);
  padding: var(--popover-padding, var(--strata-card-inset));
  background: var(--strata-color-surface-raised);
  border: 1px solid var(--strata-color-border-default);
  border-radius: var(--strata-radius-container);
  box-shadow: var(--strata-shadow-overlay);
  outline: none;
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-default);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
/* Programmatic focus on open. Pseudo-class selector so page-level `[tabindex]:focus-visible` rules can't outrank it. */
.popover:focus-visible {
  outline: none;
  border-radius: var(--strata-radius-container);
}
.popover *,
.popover *::before,
.popover *::after {
  box-sizing: border-box;
}
.popover[data-placement='top'] {
  --popover-shift: 0 var(--strata-space-1);
}
.popover[data-placement='bottom'] {
  --popover-shift: 0 calc(var(--strata-space-1) * -1);
}
.popover[data-placement='left'] {
  --popover-shift: var(--strata-space-1) 0;
}
.popover[data-placement='right'] {
  --popover-shift: calc(var(--strata-space-1) * -1) 0;
}

/* Arrow: the open path's fill covers the panel border where they meet, the stroke continues it. */
.arrow svg {
  display: block;
  inline-size: var(--strata-space-3);
  block-size: var(--strata-space-3);
}
.arrow path {
  fill: var(--strata-color-surface-raised);
  stroke: var(--strata-color-border-default);
  stroke-width: 1px;
  vector-effect: non-scaling-stroke;
}
.arrow[data-placement='bottom'] svg {
  rotate: 180deg;
}
.arrow[data-placement='left'] svg {
  rotate: -90deg;
}
.arrow[data-placement='right'] svg {
  rotate: 90deg;
}

@media (prefers-reduced-motion: no-preference) {
  .popover[data-entering] {
    animation: pop var(--strata-motion-duration-fast) var(--strata-motion-easing);
  }
  .popover[data-exiting] {
    animation: fade var(--strata-motion-duration-fast) var(--strata-motion-easing) reverse;
  }
}

@keyframes pop {
  from {
    opacity: 0;
    translate: var(--popover-shift);
  }
}
@keyframes fade {
  from {
    opacity: 0;
  }
}
